//! The public agent skill (`assets/agent_skill/SKILL.md`) is GENERATED by
//! `scripts/gen_skill_md.py` from the CLI source — never hand-edited. It is
//! what `https://riir.ai/skills/cargo-refine/SKILL.md` serves (the worker
//! vendors the generated bytes), and until 2026-11-18 a hand-maintained
//! copy of it had rotted for two months: it still taught the removed
//! `--mine`/`--unmine`/`--purge` surface, the kat_service release set, and
//! `--fix` as the primary spelling (the issue-244 rename's stale-skill
//! finding). These tests are the gate: (1) the committed bytes match what
//! the generator would emit, (2) every verb the CLI source declares is
//! rendered, (3) the binary's own `--help` surface is covered, and (4) the
//! paid-for traps stay stated. A verb the CLI gains or loses fails here
//! until the skill is regenerated — the staleness class cannot ship.

use std::path::Path;
use std::process::Command;

const SKILL: &str = include_str!("../assets/agent_skill/SKILL.md");

/// Run the generator; returns (success, combined output). Tries `python3`,
/// then `python` (the Windows boxes expose the latter).
fn run_generator(args: &[&str]) -> (bool, String) {
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    let script = manifest.join("scripts").join("gen_skill_md.py");
    for py in ["python3", "python"] {
        let ok = Command::new(py)
            .arg(&script)
            .args(args)
            .current_dir(manifest)
            .output();
        match ok {
            Ok(out) => {
                let text = format!(
                    "{}{}",
                    String::from_utf8_lossy(&out.stdout),
                    String::from_utf8_lossy(&out.stderr)
                );
                return (out.status.success(), text);
            }
            Err(_) => continue, // interpreter name not on PATH — try the next
        }
    }
    (
        false,
        "no python3/python interpreter found on PATH".to_string(),
    )
}

#[test]
fn generated_bytes_are_fresh() {
    let (ok, out) = run_generator(&["--check"]);
    assert!(ok, "generator --check failed — regenerate the skill\n{out}");
    assert!(
        out.contains("is fresh"),
        "--check passed but did not print its freshness verdict: {out}"
    );
}

#[test]
fn every_public_verb_is_rendered() {
    let (ok, out) = run_generator(&["--dump-verbs"]);
    assert!(ok, "generator --dump-verbs failed\n{out}");
    let verbs: Vec<&str> = out
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .collect();
    assert!(
        verbs.len() >= 30,
        "extraction population floor: only {} verbs rendered — the source scan regressed",
        verbs.len()
    );
    for verb in &verbs {
        let spelled = format!("cargo refine {verb}");
        assert!(
            SKILL.contains(&spelled),
            "the CLI verb `{verb}` is not rendered in the generated skill"
        );
    }
    // The full-coverage half (source verbs ⊆ CATEGORIES ∪ META, classified
    // rows ⊆ source verbs, the public/omitted split total) is the script's
    // own adjudication — re-run here so a generation-time refusal can never
    // be bypassed by shipping a stale file.
    let (ok, out) = run_generator(&["--check"]);
    assert!(ok, "generator --check (adjudication) failed\n{out}");
}

#[test]
fn the_public_skill_carries_no_token_vocabulary() {
    // The dapps worker's zero-token gate (2026-11-18 owner decree — the
    // refine product surfaces carry no token names) is mirrored HERE so a
    // template regression reds at the source before the vendored copy is
    // ever synced. The one keep-class is the service-URL env name.
    let skill = SKILL.to_lowercase();
    assert!(!skill.contains("kat "), "the skill carries 'kat '");
    assert!(!skill.contains("tuna"), "the skill carries 'tuna'");
}

/// Verb-shaped tokens after `cargo refine ` in a help page — the same shape
/// the generator scans the source for, here against the BUILT binary so the
/// gate is anchored to what actually prints.
fn binary_help_verbs(help: &str) -> Vec<String> {
    let mut verbs = Vec::new();
    let mut rest = help;
    while let Some(idx) = rest.find("cargo refine ") {
        let after = &rest[idx + "cargo refine ".len()..];
        let tok: String = after
            .chars()
            .take_while(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == '-' || *c == '|')
            .collect();
        for part in tok.split('|') {
            if part.chars().next().is_some_and(|c| c.is_ascii_lowercase()) {
                verbs.push(part.to_string());
            }
        }
        rest = &rest[idx + "cargo refine ".len()..];
    }
    verbs.sort();
    verbs.dedup();
    verbs
}

#[test]
fn binary_help_surface_is_covered() {
    // The bin target's required-features include `latent_retrieval`, so a
    // default-features test build compiles the binary to NOTHING and the
    // env path does not exist. That posture SKIPS LOUD — a deferral, never
    // a pass: the full-coverage half (`every_source_verb_is_rendered`) is
    // cfg-independent and always runs, and the guard's latent_retrieval
    // lane (Layer 5b2) builds the binary and executes this arm.
    let Some(exe) = std::option_env!("CARGO_BIN_EXE_cargo-refine") else {
        eprintln!(
            "SKIP binary_help_surface_is_covered — no cargo-refine binary at this \
             feature posture (the bin requires latent_retrieval); the source-scan \
             coverage test carries the gate here"
        );
        return;
    };
    if !Path::new(exe).exists() {
        eprintln!(
            "SKIP binary_help_surface_is_covered — the cargo-refine binary was not \
             built at this feature posture (required-features); \
             the source-scan coverage test carries the gate here"
        );
        return;
    }
    let mut verbs = Vec::new();
    for flag in ["--help", "--help-all"] {
        let out = Command::new(exe)
            .arg(flag)
            .output()
            .expect("the cargo-refine binary builds and runs --help");
        assert!(out.status.success(), "{flag} exited non-zero");
        verbs.extend(binary_help_verbs(&String::from_utf8_lossy(&out.stdout)));
    }
    verbs.sort();
    verbs.dedup();
    assert!(
        verbs.len() >= 10,
        "binary help population floor: only {} verbs printed",
        verbs.len()
    );
    // The default-features test build compiles the points/kat_service
    // fragments OUT, so this is a SUBSET check — the full-coverage half is
    // `every_source_verb_is_rendered` (the source scan is cfg-independent).
    for verb in &verbs {
        let spelled = format!("cargo refine {verb}");
        assert!(
            SKILL.contains(&spelled),
            "the built binary's help prints `{spelled}` — the skill does not render it"
        );
    }
}

#[test]
fn forbidden_stale_facts_and_required_ones() {
    // The classes the 2026-09-22 hand-written copy rotted into — none may
    // come back through a hand edit (the generator never emits them).
    for stale in [
        "--purge-server", // removed with the mining surface
        "cargo-heal",     // the pre-rename name
        "skill version 1",
        "kat_service,kat_transport", // the dead release set
    ] {
        assert!(!SKILL.contains(stale), "stale fact re-emitted: {stale}");
    }
    // The load-bearing teaching, each pinned so a template regression is a
    // red test, not a silent loss.
    for required in [
        "cargo install riir-refine",
        "fix-compile",
        "--verify-args",
        "--top-k",
        "release set: complete",
        "net-mainnet",
        "scripts/gen_skill_md.py",
        "bench-guard",
        "divergence",
        "RIIR_REFINE_AUTO_ORACLE=0",
        "WRITES by default",
        "DRY RUN",
        "never payment",
    ] {
        assert!(
            SKILL.contains(required),
            "required fact missing: {required}"
        );
    }
    let installs = SKILL
        .match_indices("https://riir.ai/skills/cargo-refine/SKILL.md")
        .count();
    assert!(
        installs >= 3,
        "the served URL must appear in both install blocks + freshness: {installs}"
    );
}
